### 9.8.1 图像处理中的直方图

**应用场景：图像直方图均衡化**

图像直方图均衡化是一种常用的图像增强技术，通过调整图像的灰度分布来增强对比度。

**实现步骤：**
1. 计算图像的灰度直方图
2. 计算累积分布函数（CDF）
3. 根据CDF映射像素值

**CUDA实现：**

```cpp
// 计算图像灰度直方图
__global__ void image_histogram_kernel(
    unsigned char* image, int* histogram, 
    int width, int height) {

    extern __shared__ int private_histogram[];

    // 初始化私有直方图（256个灰度级）
    for (int i = threadIdx.x; i < 256; i += blockDim.x) {
        private_histogram[i] = 0;
    }
    __syncthreads();

    // 处理像素
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_pixels = width * height;

    for (int i = tid; i < total_pixels; i += blockDim.x * gridDim.x) {
        int pixel_value = image[i];
        atomicAdd(&(private_histogram[pixel_value]), 1);
    }

    __syncthreads();

    // 合并到全局直方图
    for (int i = threadIdx.x; i < 256; i += blockDim.x) {
        if (private_histogram[i] > 0) {
            atomicAdd(&(histogram[i]), private_histogram[i]);
        }
    }
}

// 计算CDF并应用均衡化
__global__ void histogram_equalization_kernel(
    unsigned char* input_image, 
    unsigned char* output_image,
    int* histogram, 
    int width, int height) {

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_pixels = width * height;

    // 计算CDF（在第一个线程中完成）
    if (tid == 0) {
        int cdf = 0;
        for (int i = 0; i < 256; i++) {
            cdf += histogram[i];
            histogram[i] = cdf;
        }
    }
    __syncthreads();

    // 应用均衡化
    int cdf_min = 0;
    for (int i = 0; i < 256; i++) {
        if (histogram[i] > 0) {
            cdf_min = histogram[i];
            break;
        }
    }

    for (int i = tid; i < total_pixels; i += blockDim.x * gridDim.x) {
        int pixel_value = input_image[i];
        int cdf_value = histogram[pixel_value];
        // 均衡化公式
        int new_value = (int)(((cdf_value - cdf_min) * 255.0) / 
                              (total_pixels - cdf_min));
        output_image[i] = (unsigned char)new_value;
    }
}
```

