### 9.12.1 完整的直方图计算程序

```cpp
#include <cuda_runtime.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// 错误检查宏
#define CUDA_CHECK(call) \
    do { \
        cudaError_t err = call; \
        if (err != cudaSuccess) { \
            fprintf(stderr, "CUDA error at %s:%d: %s\n", \
                    __FILE__, __LINE__, cudaGetErrorString(err)); \
            exit(EXIT_FAILURE); \
        } \
    } while(0)

// 基本直方图内核
__global__ void histogram_basic_kernel(int* input, int* histogram, 
                                        int N, int num_bins) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        int bin = input[i] % num_bins;
        atomicAdd(&(histogram[bin]), 1);
    }
}

// 私有化直方图内核
__global__ void histogram_privatized_kernel(int* input, int* histogram, 
                                             int N, int num_bins) {
    extern __shared__ int private_histogram[];

    // 初始化私有直方图
    for (int i = threadIdx.x; i < num_bins; i += blockDim.x) {
        private_histogram[i] = 0;
    }
    __syncthreads();

    // 处理输入数据
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = tid; i < N; i += stride) {
        int bin = input[i] % num_bins;
        atomicAdd(&(private_histogram[bin]), 1);
    }

    __syncthreads();

    // 合并到全局直方图
    for (int i = threadIdx.x; i < num_bins; i += blockDim.x) {
        if (private_histogram[i] > 0) {
            atomicAdd(&(histogram[i]), private_histogram[i]);
        }
    }
}

// 完全优化的直方图内核
__global__ void histogram_optimized_kernel(int* input, int* histogram, 
                                            int N, int num_bins,
                                            int elements_per_thread) {
    extern __shared__ int private_histogram[];

    // 初始化私有直方图
    for (int i = threadIdx.x; i < num_bins; i += blockDim.x) {
        private_histogram[i] = 0;
    }
    __syncthreads();

    // 计算处理的元素范围
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int start = tid * elements_per_thread;
    int end = min(start + elements_per_thread, N);

    // 局部累积
    int local_accumulator = 0;
    int last_bin = -1;

    for (int i = start; i < end; i++) {
        int bin = input[i] % num_bins;

        if (bin != last_bin && last_bin >= 0) {
            if (local_accumulator > 0) {
                atomicAdd(&(private_histogram[last_bin]), local_accumulator);
                local_accumulator = 0;
            }
        }

        local_accumulator++;
        last_bin = bin;

        if (local_accumulator >= 8) {
            atomicAdd(&(private_histogram[bin]), local_accumulator);
            local_accumulator = 0;
            last_bin = -1;
        }
    }

    if (local_accumulator > 0) {
        atomicAdd(&(private_histogram[last_bin]), local_accumulator);
    }

    __syncthreads();

    // 合并到全局直方图
    for (int i = threadIdx.x; i < num_bins; i += blockDim.x) {
        if (private_histogram[i] > 0) {
            atomicAdd(&(histogram[i]), private_histogram[i]);
        }
    }
}

// 主机端参考实现
void histogram_cpu(int* input, int* histogram, int N, int num_bins) {
    memset(histogram, 0, num_bins * sizeof(int));
    for (int i = 0; i < N; i++) {
        int bin = input[i] % num_bins;
        histogram[bin]++;
    }
}

// 验证结果
bool verify_result(int* histogram_gpu, int* histogram_cpu, int num_bins) {
    for (int i = 0; i < num_bins; i++) {
        if (histogram_gpu[i] != histogram_cpu[i]) {
            printf("Mismatch at bin %d: GPU=%d, CPU=%d\n", 
                   i, histogram_gpu[i], histogram_cpu[i]);
            return false;
        }
    }
    return true;
}

int main() {
    // 参数设置
    int N = 10000000;  // 输入数据量
    int num_bins = 256;  // 直方图bin数量
    int elements_per_thread = 16;  // 每个线程处理的元素数

    // 分配主机内存
    int* h_input = (int*)malloc(N * sizeof(int));
    int* h_histogram_cpu = (int*)malloc(num_bins * sizeof(int));
    int* h_histogram_gpu = (int*)malloc(num_bins * sizeof(int));

    // 初始化输入数据
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        h_input[i] = rand() % 1000;  // 随机数0-999
    }

    // 分配设备内存
    int* d_input;
    int* d_histogram;
    CUDA_CHECK(cudaMalloc(&d_input, N * sizeof(int)));
    CUDA_CHECK(cudaMalloc(&d_histogram, num_bins * sizeof(int)));

    // 拷贝数据到设备
    CUDA_CHECK(cudaMemcpy(d_input, h_input, N * sizeof(int), 
                          cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemset(d_histogram, 0, num_bins * sizeof(int)));

    // 配置内核参数
    int block_size = 256;
    int num_blocks = (N + block_size - 1) / block_size;
    size_t shared_mem_size = num_bins * sizeof(int);

    // 创建CUDA事件用于计时
    cudaEvent_t start, stop;
    CUDA_CHECK(cudaEventCreate(&start));
    CUDA_CHECK(cudaEventCreate(&stop));

    // 测试基本内核
    CUDA_CHECK(cudaEventRecord(start));
    histogram_basic_kernel<<<num_blocks, block_size>>>(
        d_input, d_histogram, N, num_bins);
    CUDA_CHECK(cudaEventRecord(stop));
    CUDA_CHECK(cudaEventSynchronize(stop));

    float milliseconds = 0;
    CUDA_CHECK(cudaEventElapsedTime(&milliseconds, start, stop));
    printf("Basic kernel time: %.3f ms\n", milliseconds);

    // 拷贝结果回主机
    CUDA_CHECK(cudaMemcpy(h_histogram_gpu, d_histogram, 
                          num_bins * sizeof(int), cudaMemcpyDeviceToHost));

    // CPU参考实现
    histogram_cpu(h_input, h_histogram_cpu, N, num_bins);

    // 验证结果
    if (verify_result(h_histogram_gpu, h_histogram_cpu, num_bins)) {
        printf("Basic kernel result verified!\n");
    }

    // 重置直方图
    CUDA_CHECK(cudaMemset(d_histogram, 0, num_bins * sizeof(int)));

    // 测试私有化内核
    CUDA_CHECK(cudaEventRecord(start));
    histogram_privatized_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        d_input, d_histogram, N, num_bins);
    CUDA_CHECK(cudaEventRecord(stop));
    CUDA_CHECK(cudaEventSynchronize(stop));

    CUDA_CHECK(cudaEventElapsedTime(&milliseconds, start, stop));
    printf("Privatized kernel time: %.3f ms\n", milliseconds);

    CUDA_CHECK(cudaMemcpy(h_histogram_gpu, d_histogram, 
                          num_bins * sizeof(int), cudaMemcpyDeviceToHost));

    if (verify_result(h_histogram_gpu, h_histogram_cpu, num_bins)) {
        printf("Privatized kernel result verified!\n");
    }

    // 重置直方图
    CUDA_CHECK(cudaMemset(d_histogram, 0, num_bins * sizeof(int)));

    // 测试优化内核
    num_blocks = (N / elements_per_thread + block_size - 1) / block_size;

    CUDA_CHECK(cudaEventRecord(start));
    histogram_optimized_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        d_input, d_histogram, N, num_bins, elements_per_thread);
    CUDA_CHECK(cudaEventRecord(stop));
    CUDA_CHECK(cudaEventSynchronize(stop));

    CUDA_CHECK(cudaEventElapsedTime(&milliseconds, start, stop));
    printf("Optimized kernel time: %.3f ms\n", milliseconds);

    CUDA_CHECK(cudaMemcpy(h_histogram_gpu, d_histogram, 
                          num_bins * sizeof(int), cudaMemcpyDeviceToHost));

    if (verify_result(h_histogram_gpu, h_histogram_cpu, num_bins)) {
        printf("Optimized kernel result verified!\n");
    }

    // 清理资源
    CUDA_CHECK(cudaEventDestroy(start));
    CUDA_CHECK(cudaEventDestroy(stop));
    CUDA_CHECK(cudaFree(d_input));
    CUDA_CHECK(cudaFree(d_histogram));
    free(h_input);
    free(h_histogram_cpu);
    free(h_histogram_gpu);

    return 0;
}
